// Turn the comma separated list in Configuration into one item per domain,
// already shaped as the first round of DNS questions: fetch each domain's own
// TXT record, which is where its SPF policy lives.
const cfg = $('Configuration').first().json;
const raw = String(cfg.domains || '');

const seen = new Set();
const out = [];

for (const part of raw.split(/[,\s\n]+/)) {
  const domain = part
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/.*$/, '');

  if (!domain || !domain.includes('.')) continue;
  if (seen.has(domain)) continue;

  seen.add(domain);
  out.push({ json: { domain, qname: domain, qtype: 'TXT', purpose: 'root_spf', round: 1 } });
}

if (out.length === 0) {
  throw new Error(
    'No domains configured. Open the Configuration node and add at least one domain you own, for example example.com'
  );
}

return out;

// Read the round 1 answers, find every include: / redirect= target inside each
// SPF record, and queue TXT lookups for them. This is what lets the audit count
// NESTED lookups - whatever your vendors spend internally comes out of your own
// 10-lookup budget.
//
// Skips: targets already asked about, macro targets (%{...}) which cannot be
// expanded statically, and anything that is not a plain hostname.

// A domain usually publishes SEVERAL TXT records: site verification tokens,
// ownership proofs, and the SPF record. Each Answer row is its own record and
// they must never be concatenated - only the 255-character chunks INSIDE a
// single row get joined back together.
function txtRecordsOf(answerJson) {
  const rows = Array.isArray(answerJson && answerJson.Answer) ? answerJson.Answer : [];
  const out = [];
  for (const r of rows) {
    if (Number(r.type) !== 16) continue; // skip CNAME and other row types
    const raw = String(r.data || '');
    const chunks = raw.match(/"(?:[^"\\]|\\.)*"/g);
    const text = (chunks
      ? chunks.map((q) => q.slice(1, -1).replace(/\\"/g, '"')).join('')
      : raw
    ).trim();
    if (text) out.push(text);
  }
  return out;
}

// Returns the SPF record only, plus how many were found. Publishing two v=spf1
// records is itself a permerror under RFC 7208 section 4.5, so the count matters.
function spfOf(answerJson) {
  const spf = txtRecordsOf(answerJson).filter((t) => /^v=spf1(\s|$)/i.test(t));
  return { record: spf[0] || '', count: spf.length, all: spf };
}

function targetsOf(record) {
  const found = [];
  for (const term of record.trim().split(/\s+/).slice(1)) {
    const t = term.toLowerCase();
    let target = '';
    if (t.startsWith('redirect=')) target = t.slice(9);
    else {
      const m = /^[+\-~?]?include:(.+)$/.exec(t);
      if (m) target = m[1];
    }
    if (!target) continue;
    target = target.replace(/\.$/, '');
    if (!target || !target.includes('.') || target.includes('%')) continue;
    found.push(target);
  }
  return found;
}

const asked = new Set();
for (const it of $('Split Domains').all()) {
  asked.add(String(it.json.qname || '').toLowerCase());
}

const plans = $('Split Domains').all();
const answers = $input.all();

const spfByHost = new Map();
for (let i = 0; i < answers.length; i++) {
  const plan = plans[i].json;
  if (plan.purpose !== 'root_spf') continue;
  const rec = spfOf(answers[i].json).record;
  if (rec) spfByHost.set(String(plan.qname).toLowerCase(), rec);
}

const out = [];
for (const [host, rec] of spfByHost) {
  for (const target of targetsOf(rec)) {
    if (asked.has(target)) continue;
    asked.add(target);
    out.push({ json: { domain: host, qname: target, qtype: 'TXT', purpose: 'spf_include', round: 2 } });
  }
}

// Keep the branch alive when there is nothing left to chase.
if (out.length === 0) out.push({ json: { placeholder: true, qname: '.', qtype: 'TXT' } });

return out;

// Second expansion level. Some providers chain their includes two deep
// (your include -> vendor A -> vendor A's upstream). This node reads the round 2
// answers and queues one more layer, which covers virtually every SPF tree found
// in practice. Deeper chains are counted best effort and flagged
// "real usage may be higher" in the report.

// A domain usually publishes SEVERAL TXT records: site verification tokens,
// ownership proofs, and the SPF record. Each Answer row is its own record and
// they must never be concatenated - only the 255-character chunks INSIDE a
// single row get joined back together.
function txtRecordsOf(answerJson) {
  const rows = Array.isArray(answerJson && answerJson.Answer) ? answerJson.Answer : [];
  const out = [];
