  const found = [];
  for (const term of record.trim().split(/\s+/).slice(1)) {
    const t = term.toLowerCase();
    let target = '';
    if (t.startsWith('redirect=')) target = t.slice(9);
    else {
      const m = /^[+\-~?]?include:(.+)$/.exec(t);
      if (m) target = m[1];
    }
    if (!target) continue;
    target = target.replace(/\.$/, '');
    if (!target || !target.includes('.') || target.includes('%')) continue;
    found.push(target);
  }
  return found;
}

const asked = new Set();
for (const it of $('Split Domains').all()) {
  asked.add(String(it.json.qname || '').toLowerCase());
}
for (const it of $('Expand Includes Level 1').all()) {
  asked.add(String(it.json.qname || '').toLowerCase());
}

const plans = $('Expand Includes Level 1').all();
const answers = $input.all();

const spfByHost = new Map();
for (let i = 0; i < answers.length; i++) {
  const plan = plans[i].json;
  if (plan.purpose !== 'spf_include') continue;
  const rec = spfOf(answers[i].json).record;
  if (rec) spfByHost.set(String(plan.qname).toLowerCase(), rec);
}

const out = [];
for (const [host, rec] of spfByHost) {
  for (const target of targetsOf(rec)) {
    if (asked.has(target)) continue;
    asked.add(target);
    out.push({ json: { domain: host, qname: target, qtype: 'TXT', purpose: 'spf_include', round: 3 } });
  }
}

if (out.length === 0) out.push({ json: { placeholder: true, qname: '.', qtype: 'TXT' } });

return out;

// ---------------------------------------------------------------------------
// THE 10-DNS-LOOKUP BUDGET (RFC 7208, section 4.6.4)
//
// A receiving server may perform AT MOST ten DNS lookups while evaluating one
// SPF record. The eleventh aborts the check with "permerror": the record stops
// protecting the domain and some receivers reject even your genuine mail.
//
// Each of these terms costs ONE lookup:  include:  redirect=  a  mx  exists:  ptr
// These cost nothing:                    ip4:  ip6:  all
//
// Vendor records are charged RECURSIVELY - whatever include:sendgrid.net spends
// inside its own record comes out of YOUR budget.
//
// This node folds the three DNS rounds into one record cache, then replays that
// arithmetic offline. No network calls happen here, and the result is
// deterministic - the same records always produce the same verdict.
// ---------------------------------------------------------------------------

// A domain usually publishes SEVERAL TXT records: site verification tokens,
// ownership proofs, and the SPF record. Each Answer row is its own record and
// they must never be concatenated - only the 255-character chunks INSIDE a
// single row get joined back together.
function txtRecordsOf(answerJson) {
  const rows = Array.isArray(answerJson && answerJson.Answer) ? answerJson.Answer : [];
  const out = [];
  for (const r of rows) {
    if (Number(r.type) !== 16) continue; // skip CNAME and other row types
    const raw = String(r.data || '');
    const chunks = raw.match(/"(?:[^"\\]|\\.)*"/g);
    const text = (chunks
      ? chunks.map((q) => q.slice(1, -1).replace(/\\"/g, '"')).join('')
      : raw
    ).trim();
    if (text) out.push(text);
  }
  return out;
}

// Returns the SPF record only, plus how many were found. Publishing two v=spf1
// records is itself a permerror under RFC 7208 section 4.5, so the count matters.
function spfOf(answerJson) {
  const spf = txtRecordsOf(answerJson).filter((t) => /^v=spf1(\s|$)/i.test(t));
  return { record: spf[0] || '', count: spf.length, all: spf };
}

// --- fold the three rounds into hostname -> SPF record text -----------------
const cache = {};
const duplicateSpf = {};    // host -> how many v=spf1 records it publishes
const duplicateRecords = {}; // host -> the conflicting records themselves

const rounds = [
  { plans: $('Split Domains').all(), answers: $('Resolve DNS Round 1').all(), purpose: 'root_spf' },
  { plans: $('Expand Includes Level 1').all(), answers: $('Resolve DNS Round 2').all(), purpose: 'spf_include' },
  { plans: $('Expand Includes Level 2').all(), answers: $('Resolve DNS Round 3').all(), purpose: 'spf_include' },
];

for (const round of rounds) {
  for (let i = 0; i < round.answers.length; i++) {
    const plan = round.plans[i] && round.plans[i].json;
    if (!plan || plan.purpose !== round.purpose) continue;
    const found = spfOf(round.answers[i].json);
    if (found.record) {
      const key = String(plan.qname).toLowerCase();
      cache[key] = found.record;
      if (found.count > 1) {
        duplicateSpf[key] = found.count;
        duplicateRecords[key] = found.all.map((r) => r.slice(0, 450));
      }
    }
  }
}

// --- replay the receiver's arithmetic --------------------------------------
const VERDICT_RANK = {
  'Missing SPF': 4,
  'Unsafe +all': 4,
  'Over 10 lookups': 3,
  'Multiple SPF records': 3,
  'At the ceiling': 2,
  'Within limit': 1,
};

function evaluate(host, ctx, depth) {
  const res = { lookups: 0, unresolved: false, allMechanism: '', ptrUsed: false, macros: 0, children: [], terms: [] };

  const key = String(host || '').toLowerCase().replace(/\.$/, '');
  if (depth > 10) {
    res.unresolved = true;
    return res;
  }

  const record = cache[key];
  if (!record || !/^v=spf1(\s|$)/i.test(record)) {
    res.unresolved = true;
    return res;
  }

  // A target already walked elsewhere in THIS evaluation was already charged;
  // the include term still costs its own 1, but the subtree is not recounted.
  if (ctx.visited.has(key)) return res;
  ctx.visited.add(key);

  for (const term of record.trim().split(/\s+/).slice(1)) {
    const t = term.toLowerCase();

    // Cost nothing. Note an ip4:/ip6: block covers many addresses for free -
    // and equally, a name that resolves to several IPs still costs only 1.
    // The budget counts TERMS, never the number of addresses returned.
    if (t.startsWith('ip4:') || t.startsWith('ip6:')) {
      res.terms.push({ term, cost: 0 });
      continue;
    }
    if (t.startsWith('exp=')) continue;
    if (/^[a-z][a-z0-9._-]*=/.test(t) && !t.startsWith('redirect=')) continue; // unknown modifier

    if (t === 'all' || /^[+\-~?]all$/.test(t)) {
      if (!res.allMechanism) res.allMechanism = t;
      res.terms.push({ term, cost: 0 });
      continue;
    }

    if (t.startsWith('redirect=')) {
      res.lookups += 1;
      res.children.push({ term, cost: 1 });
      const sub = evaluate(t.slice(9), ctx, depth + 1);
      res.lookups += sub.lookups;
      res.unresolved = res.unresolved || sub.unresolved;
      res.terms.push({ term, cost: 1 + sub.lookups, nested: sub.lookups });
      if (!res.allMechanism) res.allMechanism = sub.allMechanism || 'unknown (inside redirect)';
      continue;
    }

    const inc = /^[+\-~?]?include:(.+)$/.exec(t);
    if (inc) {
      const target = inc[1];
      res.lookups += 1;
      if (target.includes('%')) {
        res.macros += 1;
        res.unresolved = true;
        res.children.push({ term, cost: 1, note: 'macro - could not expand' });
        res.terms.push({ term, cost: 1, note: 'macro, not expandable' });
        continue;
      }
      const sub = evaluate(target, ctx, depth + 1);
      res.lookups += sub.lookups;
      res.unresolved = res.unresolved || sub.unresolved;
      res.children.push({ term, cost: 1 + sub.lookups });
      res.terms.push({ term, cost: 1 + sub.lookups, nested: sub.lookups });
      continue;
    }

    const mech = /^[+\-~?]?(a|mx|ptr|exists)(?:[:/][^\s]*)?$/.exec(t);
    if (mech) {
      res.lookups += 1;
      if (mech[1] === 'ptr') res.ptrUsed = true;
      res.children.push({ term, cost: 1 });
      // One query, however many addresses come back. mx and ptr have their own
      // separate cap of 10 hosts each, which is not part of this budget.
      res.terms.push({ term, cost: 1 });
      continue;
    }
  }

  if (!res.allMechanism) res.allMechanism = '(implicit ?all)';
  return res;
}

const checkedAt = new Date().toISOString();
const domains = $('Split Domains').all().map((i) => i.json.domain);
const rows = [];

for (const domain of domains) {
  const record = cache[domain] || '';

  if (!/^v=spf1(\s|$)/i.test(record)) {
    rows.push({
      json: {
        domain,
        spf_present: 'no',
        spf_record: '',
        spf_records_all: [],
        lookup_terms: [],
        spf_lookups: '',
        spf_limit_status: 'Missing SPF',
        budget_breakdown: '',
        all_mechanism: '',
        why: 'No TXT record starting with v=spf1 was found, so nothing stops anyone sending mail as this domain.',
        recommended_action:
          'Publish a record: v=spf1 followed by every service that sends as ' + domain + ', ending in -all',
        warnings_list: ['No v=spf1 TXT record found'],
        verdict_rank: VERDICT_RANK['Missing SPF'],
        checked_at: checkedAt,
      },
    });
    continue;
  }

  const ev = evaluate(domain, { visited: new Set() }, 0);
  const lookups = ev.lookups;

  let verdict = 'Within limit';
  if (lookups > 10) verdict = 'Over 10 lookups';
  else if (lookups === 10) verdict = 'At the ceiling';
  if (ev.allMechanism === '+all') verdict = 'Unsafe +all';

  // Two v=spf1 records is a permerror in its own right (RFC 7208 s4.5): the
  // receiver cannot tell which one applies, so it stops checking entirely.
  const dupes = duplicateSpf[domain] || 0;
  if (dupes > 1 && VERDICT_RANK[verdict] < 4) verdict = 'Multiple SPF records';

  const warnings = [];
  if (dupes > 1) {
    warnings.push(dupes + ' separate v=spf1 records published - receivers permerror and stop checking');
  }
  if (verdict === 'Over 10 lookups') {
    warnings.push(lookups + ' DNS lookups used of the 10 allowed - receiving servers abort with permerror');
  } else if (verdict === 'At the ceiling') {
    warnings.push('Exactly at the 10-lookup ceiling - the next vendor include will break it');
  }
  if (ev.allMechanism === '+all') {
    warnings.push('+all authorises every server on earth to send as ' + domain);
  } else if (ev.allMechanism === '(implicit ?all)') {
    warnings.push('No all mechanism and no redirect - treated as ?all, which permits anyone');
  } else if (ev.allMechanism === '?all') {
    warnings.push('?all is neutral - unauthorised senders are neither accepted nor rejected');
  }
  if (ev.ptrUsed) warnings.push('ptr mechanism found - deprecated, slow and unreliable');
  if (ev.macros) warnings.push(ev.macros + ' macro target(s) could not be expanded - real usage may be higher');
  if (ev.unresolved && !ev.macros) {
    warnings.push('Some nested vendor records were unreachable - real usage may be higher');
  }

  const sorted = [...ev.children].sort((a, b) => b.cost - a.cost);
  const heaviest = sorted[0];

  // Plain-English explanation, derived from the same arithmetic as the verdict.
  let why;
  if (verdict === 'Multiple SPF records') {
    why =
      'This domain publishes ' + dupes + ' separate v=spf1 records. A receiver cannot tell which one applies, ' +
      'so it gives up and the domain is left unprotected.';
  } else if (ev.allMechanism === '+all') {
    why = 'The record ends in +all, which authorises every mail server on the internet to send as this domain.';
  } else if (verdict === 'Over 10 lookups') {
    why =
      'This record needs ' + lookups + ' DNS lookups, ' + (lookups - 10) + ' over the limit of 10' +
      (heaviest ? ', mostly from ' + heaviest.term + ' which costs ' + heaviest.cost + ' on its own.' : '.');
  } else if (verdict === 'At the ceiling') {
    why =
      'This record uses exactly 10 of the 10 allowed lookups' +
      (heaviest ? ', with ' + heaviest.term + ' the heaviest at ' + heaviest.cost + '.' : '.');
  } else {
    why = 'This record uses ' + lookups + ' of the 10 allowed lookups and ends in ' + ev.allMechanism + '.';
  }

  let action;
  if (verdict === 'Multiple SPF records') {
    action = 'Merge the ' + dupes + ' records into one v=spf1 TXT record, then delete the extras';
  } else if (ev.allMechanism === '+all') {
    action = 'Replace +all with -all today; anyone can currently spoof ' + domain;
  } else if (verdict === 'Over 10 lookups' && heaviest) {
    action =
      'Trim "' + heaviest.term + '" (costs ' + heaviest.cost +
      '): drop unused vendors or replace includes with flat ip4:/ip6: entries';
  } else if (verdict === 'Over 10 lookups') {
    action = 'Reduce lookups below 10 by removing or flattening includes';
  } else if (verdict === 'At the ceiling' && heaviest) {
    action = 'Pre-flatten "' + heaviest.term + '" before the next vendor tips you over';
  } else if (ev.allMechanism === '~all') {
    action = 'Inside the limit; consider tightening ~all to -all';
  } else if (ev.allMechanism === '(implicit ?all)' || ev.allMechanism === '?all') {
    action = 'Inside the limit, but add -all at the end so unauthorised senders are actually rejected';
  } else {
    action = 'None - comfortably inside the limit';
  }

  rows.push({
    json: {
      domain,
      spf_present: 'yes',
      spf_record: record.slice(0, 450),
      spf_records_all: duplicateRecords[domain] || [],
      lookup_terms: ev.terms,
      spf_lookups: lookups,
      spf_limit_status: verdict,
      budget_breakdown: sorted.length
        ? sorted.map((c) => c.term + ' (' + c.cost + ')').join(', ').slice(0, 300)
        : 'direct mechanisms only',
      all_mechanism: ev.allMechanism,
      why,
      recommended_action: action,
      warnings_list: warnings,
      verdict_rank: VERDICT_RANK[verdict],
      checked_at: checkedAt,
    },
  });
}

return rows;

// Build the Slack message and the HTML email.
//
// Design rule for this node: the reader's first question is always "how many
// lookups am I using?" - so the count leads, on every domain, healthy or not.
// The rule itself is explained once, briefly, underneath.
const cfg = $('Configuration').first().json;

const everything = $input.all().map((i) => i.json).filter((r) => r && r.domain);
if (everything.length === 0) return [];

// Anything a person has to act on: at the ceiling, over the limit, +all, or no
// record at all. There is no threshold to configure - these are exactly the
// findings this workflow exists to surface.
const findings = everything.filter((f) => f.verdict_rank >= 2);

// A manual run always reports, so you can see the audit while testing.
// A scheduled run stays silent when there is nothing to act on.
let isManualRun = false;
try {
  isManualRun = $execution.mode === 'test';
} catch (e) {
  isManualRun = false;
}
if (findings.length === 0 && !isManualRun) return [];

const healthy = everything.filter((f) => f.verdict_rank === 1);
const checked = everything.length;

const STYLE = {
  'Missing SPF': { color: '#b91c1c', order: 1 },
  'Unsafe +all': { color: '#b91c1c', order: 2 },
  'Over 10 lookups': { color: '#ea580c', order: 3 },
  'Multiple SPF records': { color: '#ea580c', order: 3 },
  'At the ceiling': { color: '#d97706', order: 4 },
  'Within limit': { color: '#2563eb', order: 5 },
};

const MAX_DETAIL = 12;         // full cards in the email
const MAX_HEALTHY_ROWS = 40;   // healthy domains listed with their count
const MAX_SLACK_DETAIL = 6;    // full cards in Slack
const SLACK_BLOCK_BUDGET = 46; // Slack hard limit is 50
const SLACK_TEXT_LIMIT = 2800; // Slack hard limit is 3000 per section

const bySeverity = (a, b) =>
  (STYLE[a.spf_limit_status] ? STYLE[a.spf_limit_status].order : 9) -
    (STYLE[b.spf_limit_status] ? STYLE[b.spf_limit_status].order : 9) ||
  Number(b.spf_lookups || 0) - Number(a.spf_lookups || 0);

findings.sort(bySeverity);
healthy.sort((a, b) => Number(b.spf_lookups || 0) - Number(a.spf_lookups || 0));

const critical = findings.filter((f) => f.verdict_rank >= 4);
const over = findings.filter((f) => f.verdict_rank === 3);
const ceiling = findings.filter((f) => f.verdict_rank === 2);
const nothingToAct = findings.length === 0;

const runDate = new Date().toISOString().slice(0, 10);
const top = findings[0] || everything[0];
const cardDomains = [...critical, ...over];

// --------------------------------------------------- the number, front and centre
// "4 of 10" on every domain. Headroom is the number people actually act on:
// it answers "can I add another vendor?" without any arithmetic.
function countOf(f) {
  if (f.spf_present === 'no') return 'no SPF record';
  // With two conflicting records the receiver never evaluates either one, so a
  // lookup count would be meaningless - and which record it came from arbitrary.
  if (f.spf_limit_status === 'Multiple SPF records') {
    return (f.spf_records_all || []).length + ' conflicting SPF records';
  }
  return f.spf_lookups + ' of 10 lookups';
}

function headroomOf(f) {
  if (f.spf_present === 'no') return '';
  if (f.spf_limit_status === 'Multiple SPF records') return 'permerror';
  const left = 10 - Number(f.spf_lookups);
  if (left > 1) return left + ' to spare';
  if (left === 1) return '1 to spare';
  if (left === 0) return 'no headroom left';
  return Math.abs(left) + ' over the limit';
}

// One sentence at the top that answers the question the reader opened with.
function headline() {
  if (checked === 1) {
    const f = everything[0];
    if (f.spf_present === 'no') {
      return 'No SPF record was found for ' + f.domain + ', so nothing stops anyone sending mail as it.';
    }
    if (f.spf_limit_status === 'Multiple SPF records') {
      return f.domain + ' publishes ' + (f.spf_records_all || []).length +
        ' separate SPF records. Receivers permerror and check none of them.';
    }
    const left = 10 - Number(f.spf_lookups);
    if (left > 0) {
      return f.domain + ' uses ' + f.spf_lookups + ' of the 10 allowed DNS lookups. Room for ' + left + ' more.';
    }
    if (left === 0) {
      return f.domain + ' uses all 10 allowed DNS lookups. The next vendor you add breaks it.';
    }
    return f.domain + ' needs ' + f.spf_lookups + ' DNS lookups, ' + Math.abs(left) + ' more than receivers allow.';
  }

  const parts = [];
  if (critical.length) parts.push(critical.length + ' unprotected');
  if (over.length) parts.push(over.length + ' broken');
  if (ceiling.length) parts.push(ceiling.length + ' at the ceiling');
  if (healthy.length) parts.push(healthy.length + ' inside the limit');

  const withRecords = everything.filter((f) => f.spf_present === 'yes');
  const heaviest = withRecords.slice().sort((a, b) => Number(b.spf_lookups) - Number(a.spf_lookups))[0];
  const tail = heaviest
    ? ' Highest usage: ' + heaviest.domain + ' at ' + heaviest.spf_lookups + ' of 10.'
    : '';

  return checked + ' domains audited - ' + parts.join(', ') + '.' + tail;
}

// ============================================================== Slack blocks
let slackTruncated = 0;

function nameSections(heading, entries) {
  const out = [];
  let cur = heading;
  let first = true;
  for (const e of entries) {
    const piece = (first ? '' : '   ') + e;
    if (cur.length + piece.length > SLACK_TEXT_LIMIT) {
      out.push(cur);
      cur = e;
    } else {
      cur += piece;
      first = false;
    }
  }
  if (cur.trim()) out.push(cur);
  return out;
}

function pushNameSections(blocks, heading, entries) {
  for (const text of nameSections(heading, entries)) {
    if (blocks.length >= SLACK_BLOCK_BUDGET) {
      slackTruncated += entries.length;
      return;
    }
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text } });
  }
}

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'SPF lookup audit', emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: '*' + headline() + '*' } },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: 'A receiving server gives up after 10 DNS lookups. It counts terms, not addresses - but vendor includes are charged recursively, so your record is usually heavier than it looks.',
      },
    ],
  },
];

if (cardDomains.length) {
  blocks.push({ type: 'divider' });
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: critical.length ? ':rotating_light: *Fix immediately*' : ':large_orange_circle: *Broken - receivers will permerror*',
    },
  });

  for (const f of cardDomains.slice(0, MAX_SLACK_DETAIL)) {
    blocks.push({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text:
          '*`' + f.domain + '`*  ' + countOf(f) + '\n' + f.why + '\n:arrow_right: ' + f.recommended_action,
      },
    });
  }

  if (cardDomains.length > MAX_SLACK_DETAIL) {
    pushNameSections(
      blocks,
      '_Also failing, details in the email:_\n',
      cardDomains.slice(MAX_SLACK_DETAIL).map((f) => '`' + f.domain + '`')
    );
  }
}

if (ceiling.length) {
  blocks.push({ type: 'divider' });
  pushNameSections(
    blocks,
    ':warning: *At the ceiling - exactly 10 of 10, one vendor from breaking*\n',
    ceiling.map((f) => '`' + f.domain + '`')
  );
}

if (healthy.length) {
  blocks.push({ type: 'divider' });
  pushNameSections(
    blocks,
    ':white_check_mark: *Inside the limit (' + healthy.length + ')*\n',
    healthy.map((f) => '`' + f.domain + '` ' + f.spf_lookups + '/10')
  );
}

if (slackTruncated) {
  blocks.push({
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: 'Slack caps a message at 50 blocks, so ' + slackTruncated + ' domain(s) did not fit. All of them are in the email.',
      },
    ],
  });
}

// ===================================================================== Email
const FONT = 'font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Helvetica,Arial,sans-serif';

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function chip(v) {
  const c = (STYLE[v] || STYLE['Within limit']).color;
  return (
    '<span style="display:inline-block;background:' + c +
    ';color:#ffffff;border-radius:4px;padding:2px 8px;' + FONT +
    ';font-size:10px;font-weight:700;letter-spacing:0.4px;text-transform:uppercase;">' + esc(v) + '</span>'
  );
}

function heading(text, color) {
  return (
    '<tr><td style="padding:20px 20px 6px 20px;border-top:1px solid #e2e8f0;">' +
    '<div style="' + FONT + ';font-size:14px;font-weight:800;color:' + color + ';">' + esc(text) + '</div></td></tr>'
  );
}

// Full card: the count, then why, then the one thing to do about it.
function detailRow(f) {
  const head = countOf(f) + (headroomOf(f) ? ' &nbsp;&middot;&nbsp; ' + headroomOf(f) : '');
  return (
    '<tr><td style="padding:12px 20px;border-bottom:1px solid #f1f5f9;">' +
    '<div style="' + FONT + ';font-size:15px;font-weight:700;color:#0f172a;word-break:break-all;">' +
    esc(f.domain) + ' &nbsp;' + chip(f.spf_limit_status) + '</div>' +
    '<div style="' + FONT + ';font-size:13px;font-weight:600;color:#0f172a;padding-top:4px;">' + head + '</div>' +
    '<div style="' + FONT + ';font-size:13px;line-height:1.6;color:#475569;padding-top:4px;">' + esc(f.why) + '</div>' +
    '<div style="' + FONT + ';font-size:13px;color:#0f172a;padding-top:6px;">&rarr; ' + esc(f.recommended_action) + '</div>' +
    recordBlock(f) +
    termTable(f) +
    '</td></tr>'
  );
}

// Healthy domain, shown in full: the count, the record, and where it goes.
function healthyDetailRow(f) {
  const head = countOf(f) + (headroomOf(f) ? ' &nbsp;&middot;&nbsp; ' + headroomOf(f) : '');
  return (
    '<tr><td style="padding:12px 20px;border-bottom:1px solid #f1f5f9;">' +
    '<div style="' + FONT + ';font-size:15px;font-weight:700;color:#0f172a;word-break:break-all;">' +
    esc(f.domain) + '</div>' +
    '<div style="' + FONT + ';font-size:13px;font-weight:600;color:#0f172a;padding-top:4px;">' + head + '</div>' +
    recordBlock(f) +
    termTable(f) +
    '</td></tr>'
  );
}

// Compact row: still carries the count, which is the whole point.
function countRow(f) {
  return (
    '<tr><td style="padding:7px 20px;border-bottom:1px solid #f8fafc;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>' +
    '<td style="' + FONT + ';font-size:13px;color:#334155;word-break:break-all;">' + esc(f.domain) + '</td>' +
    '<td align="right" style="' + FONT + ';font-size:13px;font-weight:700;color:#0f172a;white-space:nowrap;">' +
    esc(countOf(f)) + '</td></tr></table></td></tr>'
  );
}

// The record itself, monospaced and wrapped.
function recordBlock(f) {
  const all = f.spf_records_all || [];
  if (all.length > 1) {
    return (
      '<div style="' + FONT + ';font-size:11px;font-weight:700;color:#94a3b8;padding-top:10px;' +
      'letter-spacing:0.5px;text-transform:uppercase;">Your ' + all.length + ' conflicting records</div>' +
      all
        .map(
          (r, n) =>
            '<div style="font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;' +
            'line-height:1.6;color:#334155;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;' +
            'padding:9px 11px;margin-top:4px;word-break:break-all;">' +
            '<span style="color:#b91c1c;font-weight:700;">' + (n + 1) + '.</span> ' + esc(r) + '</div>'
        )
        .join('')
    );
  }
  if (!f.spf_record) return '';
  return (
    '<div style="' + FONT + ';font-size:11px;font-weight:700;color:#94a3b8;padding-top:10px;' +
    'letter-spacing:0.5px;text-transform:uppercase;">Your record</div>' +
    '<div style="font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;' +
    'line-height:1.6;color:#334155;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;' +
    'padding:9px 11px;margin-top:4px;word-break:break-all;">' + esc(f.spf_record) + '</div>'
  );
}

// Where the lookups actually go, term by term, in the order they appear in the
// record. Free terms are shown too, so the arithmetic is checkable by eye.
function termTable(f) {
  // Counting one of two conflicting records would imply the receiver picks one.
  // It does not - it gives up. So no table here.
  if (f.spf_limit_status === 'Multiple SPF records') return '';
  const terms = Array.isArray(f.lookup_terms) ? f.lookup_terms : [];
  if (!terms.length) return '';

  const maxCost = Math.max(...terms.map((t) => Number(t.cost) || 0));

  const rows = terms
    .map((t) => {
      const cost = Number(t.cost) || 0;
      const heavy = cost > 0 && cost === maxCost && maxCost > 1;
      const label = cost === 0 ? 'free' : cost === 1 ? '1 lookup' : cost + ' lookups';
      const note = t.nested
        ? ' <span style="color:#94a3b8;">(1 + ' + t.nested + ' nested)</span>'
        : t.note
        ? ' <span style="color:#94a3b8;">(' + esc(t.note) + ')</span>'
        : '';
      return (
        '<tr><td style="padding:3px 0;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;' +
        'font-size:12px;color:' + (cost === 0 ? '#94a3b8' : '#334155') + ';word-break:break-all;">' +
        esc(t.term) + '</td>' +
        '<td align="right" style="padding:3px 0 3px 12px;' + FONT + ';font-size:12px;white-space:nowrap;' +
        'color:' + (cost === 0 ? '#94a3b8' : '#0f172a') + ';font-weight:' + (heavy ? '800' : '400') + ';">' +
        label + note + '</td></tr>'
      );
    })
    .join('');

  return (
    '<div style="' + FONT + ';font-size:11px;font-weight:700;color:#94a3b8;padding-top:12px;' +
    'letter-spacing:0.5px;text-transform:uppercase;">Where the lookups go</div>' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:4px;">' +
    rows +
    '<tr><td style="padding:7px 0 0 0;border-top:1px solid #e2e8f0;' + FONT + ';font-size:12px;font-weight:700;color:#0f172a;">Total</td>' +
    '<td align="right" style="padding:7px 0 0 0;border-top:1px solid #e2e8f0;' + FONT +
    ';font-size:12px;font-weight:800;color:#0f172a;white-space:nowrap;">' + esc(countOf(f)) + '</td></tr>' +
    '</table>'
  );
}

// Small estates get the record and breakdown for every domain; large ones only
// for the domains that need action, so the message stays readable.
const SHOW_DETAIL_FOR_ALL = checked <= 5;

let body = '';

if (cardDomains.length) {
  body += heading('Fix now (' + cardDomains.length + ')', critical.length ? '#b91c1c' : '#ea580c');
  body += cardDomains.slice(0, MAX_DETAIL).map(detailRow).join('');
  if (cardDomains.length > MAX_DETAIL) {
    body += cardDomains.slice(MAX_DETAIL).map(countRow).join('');
  }
}

if (ceiling.length) {
  body += heading('At the ceiling - 10 of 10 (' + ceiling.length + ')', '#d97706');
  body += ceiling.slice(0, MAX_DETAIL).map(detailRow).join('');
  if (ceiling.length > MAX_DETAIL) {
    body += ceiling.slice(MAX_DETAIL).map(countRow).join('');
  }
}

if (healthy.length) {
  // With one domain the headline already gave the count, so skip the heading
  // and go straight to the record and the breakdown.
  if (!(checked === 1 && nothingToAct)) {
    body += heading('Inside the limit (' + healthy.length + ')', '#2563eb');
  }
  body += SHOW_DETAIL_FOR_ALL
    ? healthy.map(healthyDetailRow).join('')
    : healthy.slice(0, MAX_HEALTHY_ROWS).map(countRow).join('');
  if (!SHOW_DETAIL_FOR_ALL && healthy.length > MAX_HEALTHY_ROWS) {
    body +=
      '<tr><td style="padding:10px 20px;' + FONT + ';font-size:12px;color:#94a3b8;">and ' +
      (healthy.length - MAX_HEALTHY_ROWS) + ' more inside the limit</td></tr>';
  }
}

const html =
  '<div style="background:#f1f5f9;padding:24px 0;">' +
  '<table role="presentation" width="620" cellpadding="0" cellspacing="0" border="0" ' +
  'style="width:100%;max-width:620px;margin:0 auto;background:#ffffff;border-radius:10px;overflow:hidden;">' +

  '<tr><td style="background:' + (STYLE[top.spf_limit_status] || STYLE['Within limit']).color + ';height:5px;"></td></tr>' +

  // Title, then the answer, then the rule. In that order.
  '<tr><td style="padding:22px 20px 0 20px;">' +
  '<div style="' + FONT + ';font-size:12px;font-weight:700;letter-spacing:0.6px;text-transform:uppercase;color:#94a3b8;">' +
  'SPF lookup audit &nbsp;&middot;&nbsp; ' + runDate + '</div>' +
  '<div style="' + FONT + ';font-size:19px;font-weight:800;line-height:1.4;color:#0f172a;padding-top:8px;">' +
  esc(headline()) + '</div></td></tr>' +

  '<tr><td style="padding:14px 20px 4px 20px;">' +
  '<div style="' + FONT + ';font-size:12px;line-height:1.7;color:#64748b;background:#f8fafc;border-left:3px solid #cbd5e1;padding:12px 14px;">' +
  '<strong style="color:#334155;">Why 10 matters.</strong> When a server receives mail claiming to be from you, it reads ' +
  'your SPF record to check the sender is authorised - but it will only make <strong>10 DNS lookups</strong> doing so. ' +
  'The 11th aborts the check with <em>permerror</em>: your record stops protecting the domain, and some servers reject ' +
  'even your genuine mail. Each <code>include:</code>, <code>redirect=</code>, <code>a</code>, <code>mx</code>, ' +
  '<code>exists:</code> and <code>ptr</code> costs one. <code>ip4:</code>, <code>ip6:</code> and <code>all</code> are free. ' +
  'A name that resolves to several IP addresses still costs <strong>one</strong> - the budget counts terms, ' +
  'not addresses. What inflates it is nesting: a vendor include is charged recursively, so 5 includes can ' +
  'easily cost 12.' +
  '</div></td></tr>' +

  '<tr><td style="padding:8px 0 0 0;"><table role="presentation" width="100%" cellpadding="0" ' +
  'cellspacing="0" border="0">' + body + '</table></td></tr>' +

  '<tr><td style="padding:16px 20px 20px 20px;' + FONT + ';font-size:11px;line-height:1.7;color:#94a3b8;border-top:1px solid #e2e8f0;">' +
  esc(String(cfg.domains || '')) + '<br>' +
  'Records read from Google DNS-over-HTTPS, every include chased two levels deep, then the RFC 7208 lookup ' +
  'arithmetic replayed offline. Only DNS TXT records are read - this workflow never opens, sends or scans email.' +
  '</td></tr></table></div>';

const subjectParts = [];
if (critical.length) subjectParts.push(critical.length + ' unprotected');
if (over.length) subjectParts.push(over.length + ' broken');
if (ceiling.length) subjectParts.push(ceiling.length + ' at ceiling');

const subject = nothingToAct
  ? (checked === 1
      ? '[OK] SPF audit: ' + everything[0].domain + ' at ' + everything[0].spf_lookups + ' of 10 lookups'
      : '[OK] SPF audit: all ' + checked + ' domains inside the 10-lookup limit') + ' on ' + runDate
  : '[' + top.spf_limit_status + '] SPF audit: ' + subjectParts.join(', ') + ' on ' + runDate;

return [
  {
    json: {
      subject,
      html,
      slackBlocks: { blocks },
      slackChannel: String(cfg.slackChannel || 'security-alerts'),
      summary: {
        runDate,
        checked,
        critical: critical.length,
        overLimit: over.length,
        atCeiling: ceiling.length,
        healthy: healthy.length,
        nothingToAct,
        headline: headline(),
      },
    },
  },
];
